INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ISL_MODERN','Modern Sufism (19th–21st c.)',1850,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_NURSI_RISALE','primary text','Said Nursi, Risale-i Nur (Epistles of Light, early 20th c.)','Islamic/Sufi'),
 ('SRC_ALAWI_DIWAN','primary text','Ahmad al-Alawi, Diwan and treatises (early 20th c., as transmitted in M. Lings, A Sufi Saint of the Twentieth Century)','Islamic/Sufi'),
 ('SRC_BAMBA_KHASAID','primary text','Ahmadou Bamba (Cheikh Amadou Bamba), Khassaïd (devotional poems of the Mouridiyya)','Islamic/Sufi'),
 ('SRC_NIASSE_KASHIF','primary text','Ibrahim Niasse, Kashif al-ilbas (Removal of Confusion, Tijani revival doctrine)','Islamic/Sufi'),
 ('SRC_INAYAT_KHAN_MESSAGE','primary text','Hazrat Inayat Khan, The Sufi Message (collected teachings, Western Sufi Order)','Islamic/Sufi')
INSERT INTO _e VALUES
 ('ENT_SUF_IBN_IDRIS','Ahmad ibn Idris','Saint','Modern Sufi reformer','Islamic/Sufi','Sufi revival; tariqa Muhammadiyya; hadith-centred mysticism','A','Moroccan reformer (d. 1837), fountainhead of the 19th-c. ''neo-Sufi'' revival; teacher of al-Sanusi and the Idrisi family of orders.'),
 ('ENT_SUF_SANUSI','Muhammad ibn Ali al-Sanusi','Saint','Tariqa founder','Islamic/Sufi','Sanusiyya order; Saharan reform Sufism; zawiya network','A','Founder of the Sanusiyya (d. 1859); student of Ahmad ibn Idris; built a reformist lodge network across Libya/Sahara.'),
 ('ENT_SUF_SANUSIYYA','Sanusiyya','Collective','Sufi order','Islamic/Sufi','Saharan reform tariqa; zawiya network; later Libyan state','A','Reformist Sufi order founded by al-Sanusi, rooted in the teaching of Ahmad ibn Idris; politically dominant in Cyrenaica/Libya.'),
 ('ENT_SUF_ALAWI','Ahmad al-Alawi','Saint','Tariqa founder','Islamic/Sufi','Alawiyya order; Shadhili-Darqawi mysticism; Akbari metaphysics','A','Algerian saint (d. 1934), founder of the Alawiyya, a Darqawi-Shadhili branch; subject of Martin Lings'' study; influential on Western Sufism.'),
 ('ENT_SUF_ALAWIYYA','Alawiyya','Collective','Sufi order','Islamic/Sufi','Shadhili-Darqawi branch; Algerian/Mediterranean spread; Western reception','A','Sufi order founded by Ahmad al-Alawi, a branch of the Darqawiyya; widely influential including on European converts.'),
 ('ENT_SUF_NURSI','Said Nursi','Saint','Modern Sufi reformer','Islamic/Sufi','Risale-i Nur; faith-renewal movement; Qur''anic exegesis','A','Ottoman/Turkish scholar (d. 1960), author of the Risale-i Nur; founder-inspiration of the Nurcu faith-renewal movement; Naqshbandi-influenced.'),
 ('ENT_SUF_NURCU','Nurcu Movement','Collective','Sufi order','Islamic/Sufi','Risale-i Nur readers'' movement; modern Turkish faith renewal','A','Faith-renewal movement of the readers of Said Nursi''s Risale-i Nur; a modern Sufism-inflected community rather than a classical tariqa.'),
 ('ENT_SUF_BAMBA','Ahmadou Bamba','Saint','Tariqa founder','Islamic/Sufi','Mouridiyya order; Senegalese Sufism; sanctified labour','A','Senegalese saint Cheikh Amadou Bamba (d. 1927), founder of the Mouridiyya; Qadiri-rooted; venerated at Touba.'),
 ('ENT_SUF_MOURIDIYYA','Mouridiyya','Collective','Sufi order','Islamic/Sufi','Senegalese Sufi order; Touba pilgrimage; work-as-worship ethic','A','Major Senegalese Sufi order founded by Ahmadou Bamba; centred on the holy city of Touba.'),
 ('ENT_SUF_NIASSE','Ibrahim Niasse','Saint','Modern Sufi reformer','Islamic/Sufi','Tijani revival (Fayda); West African mass Sufism; tarbiya','A','Senegalese shaykh (d. 1975), leader of the Tijani Fayda (''flood'') revival; mass spiritual-training movement across West Africa and Nigeria.'),
 ('ENT_SUF_HAMALLAH','Shaykh Hamallah','Saint','Tariqa founder','Islamic/Sufi','Hamalliyya (Tijani offshoot); West African reform; eleven-bead litany','B','Malian Tijani saint (Ahmad Hamahullah, d. 1943), eponym of the Hamalliyya, a reformist Tijani branch repressed under French colonial rule.'),
 ('ENT_SUF_HAFIZ_TIJANI','Muhammad al-Hafiz al-Tijani','Saint','Modern Sufi reformer','Islamic/Sufi','Egyptian Tijani revival; hadith scholarship; tariqa renewal','B','Egyptian Tijani shaykh (d. 1978) who revitalised the Tijaniyya in Egypt and emphasised its hadith and scholarly credentials.'),
 ('ENT_SUF_IBN_AL_HABIB','Muhammad ibn al-Habib','Saint','Tariqa founder','Islamic/Sufi','Darqawi-Habibiyya; Moroccan Shadhili Sufism; Diwan of litanies','B','Moroccan saint (d. 1972) of the Darqawi-Shadhili line, shaykh of the Habibiyya; his Diwan is widely recited; teacher of early Western converts.'),
 ('ENT_SUF_INAYAT_KHAN','Hazrat Inayat Khan','Saint','Sufi missionary','Islamic/Sufi','Chishti transmission to the West; universal Sufism; Sufi Order in the West','A','Indian musician-mystic (d. 1927), Chishti-initiated, who founded the Sufi Order in the West and introduced Sufism to Europe and America in a universalist form.'),
 ('ENT_SUF_PIR_VILAYAT','Pir Vilayat Inayat Khan','Saint','Sufi missionary','Islamic/Sufi','Western universal Sufism; Sufi Order International; meditation teaching','B','Son and successor of Hazrat Inayat Khan (d. 2004); led the Sufi Order International, spreading Inayati universal Sufism in the West.'),
 ('ENT_SUF_BAWA','Bawa Muhaiyaddeen','Saint','Sufi missionary','Islamic/Sufi','Tamil-Sri Lankan Sufism to America; Bawa Muhaiyaddeen Fellowship','B','Sri Lankan Tamil mystic (d. 1986) who founded the Bawa Muhaiyaddeen Fellowship in Philadelphia, transmitting a universalist Sufi teaching in the West.'),
 ('ENT_SUF_OZAK','Muzaffer Ozak','Saint','Sufi missionary','Islamic/Sufi','Jerrahi-Halveti order; Turkish Sufism to America','B','Turkish shaykh (d. 1985) of the Halveti-Jerrahi order who established Jerrahi communities in North America and Europe.'),
 ('ENT_SUF_NAZIM_HAQQANI','Nazim al-Haqqani','Saint','Sufi missionary','Islamic/Sufi','Naqshbandi-Haqqani order; global Naqshbandi spread; Cyprus center','B','Turkish-Cypriot Naqshbandi shaykh (d. 2014), head of the Naqshbandi-Haqqani order, which spread the Naqshbandi-Khalidi line worldwide including to the West.'),
 ('ENT_SUF_HAQQANI','Naqshbandi-Haqqani','Collective','Sufi order','Islamic/Sufi','Global Naqshbandi-Khalidi branch; transnational Sufism','B','Transnational Naqshbandi-Khalidi suborder led by Nazim al-Haqqani; a major vehicle of Naqshbandi Sufism in the modern West.');
