INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_SUF_SANUSI','member_of','ENT_SUF_SANUSIYYA','high','Al-Sanusi is the eponymous founder of the Sanusiyya order.'),
 ('ENT_SUF_SANUSI','taught_by','ENT_SUF_IBN_IDRIS','high','Al-Sanusi was a leading disciple of Ahmad ibn Idris before founding the Sanusiyya.'),
 ('ENT_SUF_ALAWI','member_of','ENT_SUF_ALAWIYYA','high','Ahmad al-Alawi is the eponymous founder of the Alawiyya order.'),
 ('ENT_SUF_ALAWIYYA','member_of','ENT_SUF_DARQAWIYYA','high','The Alawiyya is a branch of the Darqawi-Shadhili line, descending through the Darqawiyya.'),
 ('ENT_SUF_ALAWI','reception_of','ENT_SUF_DARQAWI','high','Al-Alawi''s lineage runs through the Darqawiyya founded by al-Darqawi (via al-Buzidi).'),
 ('ENT_SUF_ALAWI','reception_of','ENT_SUF_IBN_ARABI','medium','Al-Alawi taught Akbari metaphysics (wahdat al-wujud) drawn from Ibn Arabi.'),
 ('ENT_SUF_NURSI','member_of','ENT_SUF_NURCU','high','Said Nursi is the founding inspiration and author whose Risale-i Nur defines the Nurcu movement.'),
 ('ENT_SUF_NURSI','reception_of','ENT_SUF_NAQSHBANDI_KHALID','medium','Nursi''s early formation was within the Naqshbandi-Khalidi milieu of eastern Anatolia, which shaped the Risale-i Nur.'),
 ('ENT_SUF_BAMBA','member_of','ENT_SUF_MOURIDIYYA','high','Ahmadou Bamba is the eponymous founder of the Mouridiyya.'),
 ('ENT_SUF_BAMBA','reception_of','ENT_SUF_JILANI','high','Bamba was first initiated in the Qadiriyya founded by Abd al-Qadir al-Jilani before establishing the Mouridiyya.'),
 ('ENT_SUF_NIASSE','member_of','ENT_SUF_TIJANIYYA','high','Ibrahim Niasse led the Fayda revival within the Tijaniyya.'),
 ('ENT_SUF_NIASSE','reception_of','ENT_SUF_TIJANI','high','Niasse''s Fayda movement claims and develops the spiritual transmission of Ahmad al-Tijani.'),
 ('ENT_SUF_HAMALLAH','member_of','ENT_SUF_TIJANIYYA','high','The Hamalliyya is a reformist branch within the Tijaniyya.'),
 ('ENT_SUF_HAMALLAH','reception_of','ENT_SUF_TIJANI','high','Shaykh Hamallah claimed transmission of the Tijani way founded by Ahmad al-Tijani (the eleven-bead controversy concerns Tijani litany practice).'),
 ('ENT_SUF_HAFIZ_TIJANI','member_of','ENT_SUF_TIJANIYYA','high','Muhammad al-Hafiz revitalised the Tijaniyya in Egypt.'),
 ('ENT_SUF_HAFIZ_TIJANI','reception_of','ENT_SUF_TIJANI','high','His revival explicitly transmits the way of Ahmad al-Tijani.'),
 ('ENT_SUF_IBN_AL_HABIB','member_of','ENT_SUF_DARQAWIYYA','high','Muhammad ibn al-Habib''s Habibiyya is a branch of the Darqawi-Shadhili line.'),
 ('ENT_SUF_IBN_AL_HABIB','reception_of','ENT_SUF_DARQAWI','high','His silsila descends from the Darqawiyya founded by al-Darqawi.'),
 ('ENT_SUF_INAYAT_KHAN','reception_of','ENT_SUF_CHISHTI','high','Inayat Khan was initiated in the Chishti order and transmitted a Chishti-rooted Sufism to the West.'),
 ('ENT_SUF_INAYAT_KHAN','reception_of','ENT_SUF_CHISHTI_MUIN','medium','His Chishti lineage traces to Mu''in al-Din Chishti, the order''s founder in India.'),
 ('ENT_SUF_PIR_VILAYAT','taught_by','ENT_SUF_INAYAT_KHAN','high','Pir Vilayat was the son and designated successor of Hazrat Inayat Khan.'),
 ('ENT_SUF_OZAK','reception_of','ENT_SUF_KHALWATIYYA','high','Muzaffer Ozak headed the Halveti-Jerrahi order, a branch of the Khalwatiyya.'),
 ('ENT_SUF_BAWA','aligned_with','ENT_SUF_INAYAT_KHAN','low','Functional alignment: both are 20th-c. founders of universalist Sufi communities in the West; Bawa has no documented formal tariqa silsila, so this is a comparative (not lineal) link.'),
 ('ENT_SUF_NAZIM_HAQQANI','member_of','ENT_SUF_HAQQANI','high','Nazim al-Haqqani is the eponymous head of the Naqshbandi-Haqqani order.'),
 ('ENT_SUF_HAQQANI','member_of','ENT_SUF_NAQSHBANDI','high','The Naqshbandi-Haqqani is a modern transnational branch of the Naqshbandiyya.'),
 ('ENT_SUF_NAZIM_HAQQANI','reception_of','ENT_SUF_NAQSHBANDI_KHALID','high','The Haqqani silsila descends through the Naqshbandi-Khalidi line of Khalid al-Baghdadi.');
